async function main() {
  const papers = await prisma.paper.findMany();
  const byName = Object.fromEntries(papers.map((p) => [p.name, p.id]));
  let saved = 0, skipped = 0;
  for (const r of RATES) {
    const paperId = byName[r.paperName];
    if (!paperId) { skipped++; console.log("No paper named", r.paperName); continue; }
    const { paperName, ...rest } = r;
    const data = {
      ...rest,
      paperId,
      effectiveDate: r.effectiveDate ? new Date(r.effectiveDate) : null,
      inactiveDate: r.inactiveDate ? new Date(r.inactiveDate) : null,
    };
    await prisma.rate.upsert({ where: { newzwareId: r.newzwareId }, create: data, update: data });
    saved++;
  }
  const counts = await prisma.rate.groupBy({ by: ["paperId"], _count: true });
  console.log("Saved:", saved, " Skipped:", skipped);
  for (const c of counts) console.log(papers.find((p) => p.id === c.paperId)?.name, c._count);
}
main().catch((e) => { console.error(e); process.exit(1); }).finally(() => prisma.$disconnect());
